 public static object Run(Store store,string projectId="",string enemyId="",bool minimizeOnly=false){Store.Closed();var saves=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Kingsway");Dictionary<string,string> Snapshot()=>Directory.Exists(saves)?Directory.GetFiles(saves,"*",SearchOption.AllDirectories).ToDictionary(p=>p,Game.Hash):new();var before=Snapshot();Json.Save(Path.Combine(store.Root,"Evidence","saves-before.json"),before);store.Build(true,projectId,enemyId,null,minimizeOnly);var start=DateTime.UtcNow;var log=Path.Combine(store.Root,"Evidence","engine-debug.log");var psi=new ProcessStartInfo(Path.Combine(store.GameRoot,"Kingsway.exe")){WorkingDirectory=store.GameRoot,UseShellExecute=false,WindowStyle=ProcessWindowStyle.Normal};psi.ArgumentList.Add("-game");psi.ArgumentList.Add(Path.Combine(store.GameRoot,"data.v2-test.win"));psi.ArgumentList.Add("-debugoutput");psi.ArgumentList.Add(log);
  bool exited=false;bool terminatedByHarness=false;string liveReport=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"KingswayWorkshopV2Test","v2-tests.txt");using(var proc=Process.Start(psi)!){_ = LaunchWindow.Focus(proc);var deadline=DateTime.UtcNow.AddSeconds(120);while(DateTime.UtcNow<deadline){if(proc.WaitForExit(200)){exited=true;break;}if(LaunchWindow.Diagnostics(proc)!="")break;try{if(File.Exists(liveReport)&&File.GetLastWriteTimeUtc(liveReport)>=start&&File.ReadAllText(liveReport).Contains("RESULT:")){exited=proc.WaitForExit(1500);break;}}catch(IOException){/* The runner briefly owns its report while appending a line. */}}if(!exited){File.WriteAllText(Path.Combine(store.Root,"Evidence","engine-native-error.txt"),LaunchWindow.Diagnostics(proc));proc.Kill();proc.WaitForExit();terminatedByHarness=true;}}
  var after=Snapshot();Json.Save(Path.Combine(store.Root,"Evidence","saves-after.json"),after);bool unchanged=before.Count==after.Count&&before.All(kv=>after.TryGetValue(kv.Key,out var h)&&h==kv.Value);Json.Save(Path.Combine(store.Root,"Evidence","save-integrity.json"),new{unchanged,files=before.Count});if(!unchanged)throw new Exception("Save integrity check failed");string testSave=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"KingswayWorkshopV2Test");string report=Path.Combine(testSave,"v2-tests.txt");if(!File.Exists(report)||File.GetLastWriteTimeUtc(report)<start)throw new Exception("Engine produced no fresh report. See "+log);string text=File.ReadAllText(report);File.Copy(report,Path.Combine(store.Root,"Evidence",minimizeOnly?"minimize-engine-tests.txt":projectId==""?"engine-tests.txt":"preview-tests.txt"),true);foreach(var name in new[]{"v2-battle.png","v2-victory.png","v2-expansion.png","v3-windows.png","v2-path-samples.json","v2-minimize-samples.jsonl"})if(File.Exists(Path.Combine(testSave,name)))File.Copy(Path.Combine(testSave,name),Path.Combine(store.Root,"Evidence",name),true);foreach(var screenshot in Directory.GetFiles(testSave,"v2-minimize-*.png"))File.Copy(screenshot,Path.Combine(store.Root,"Evidence",Path.GetFileName(screenshot)),true);if(!System.Text.RegularExpressions.Regex.IsMatch(text,@"RESULT: \d+ assertions, 0 failures"))throw new Exception("Engine verification failed:\n"+text);var result=new{passed=true,saveFilesUnchanged=before.Count,terminatedByHarness,report=text};Json.Save(Path.Combine(store.Root,"Evidence",minimizeOnly?"minimize-engine-verification.json":projectId==""?"engine-verification.json":"preview-verification.json"),result);return result;
